    row_divs = [r for r in range(h) if all(grid[r][c] == 2 for c in range(w))]
    col_divs = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 2)]
    if not obj:
        return out
